use verus::prelude::*;

/// Given a non-empty input vector of ASCII lowercase letters where
/// the first character is in the range 'a'..='y', returns a new
/// Vec<char> containing the successor of the first character
/// (in ASCII) followed by a newline character.
#[requires(input.len() >= 1)]
#[requires(input[0] >= 'a')]
#[requires(input[0] <= 'y')]
#[ensures(|res: Vec<char>| res.len() == 2)]
#[ensures(|res: Vec<char>| (res[0] as u8) == (input[0] as u8) + 1)]
#[ensures(|res: Vec<char>| res[1] == '\n')]
pub fn solve(input: Vec<char>) -> Vec<char> {
    // We know input is non-empty and input[0] is in 'a'..='y'.
    let first = input[0];
    // Compute the successor in the ASCII table:
    // 'a'..='y' are contiguous, so adding 1 is safe.
    let successor = ((first as u8) + 1) as char;
    // Return a new Vec<char> containing the successor and a newline.
    vec![successor, '\n']
}

